head.script:
scwin.test = function(row, col) {
    var obj = {};
    if (row == 0) {
        obj.increment = 2;
        obj.minValue = 0;
        obj.maxValue = 10;
        return obj;
    } else if (row == 1) {
        obj.increment = 4;
        obj.minValue = 0;
        obj.maxValue = 20;
        return obj;
    } else if (row == 2) {
        obj.increment = 8;
        obj.minValue = 0;
        obj.maxValue = 40;
        return obj;
    }
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
    //if ( document.createEvent ) {
    //	var evt = document.createEvent('MouseEvents');
    //	evt.initEvent('dblclick', true, false);
    //	node.dispatchEvent(evt);	
    //} else if( document.createEventObject ) {
    //	node.fireEvent('ondblclick') ;	
    //} else if (typeof node.ondblclick == 'function' ) {
    //	node.ondblclick();	
    //}
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById(id);
    scwin.fireDbClick(el);
    //var ev = document.createEvent("MouseEvents");
    //ev.initEvent("dblclick", true, true);
    //el.dispatchEvent(ev);
}
