    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'G_'+$p.id+'wq_uuid_3___spinner_col2___input').value == '3'", "true");
